      for (const [it, n] of Object.entries(a.consume || {})) if ((s.items[it] || 0) < n) return fail(`没有${D.items[it].label}了`);
      if (a.kind === "pay_rent" && !(s.owed > 0)) return fail("不欠房租");
      if (a.kind === "pay_rent" && s.money < s.owed) return fail("钱不够");
