    const fareKm = (km) => { for (const [lim, y] of R.fare.bands) if (km <= lim) return y; return R.fare.bands[R.fare.bands.length - 1][1]; };
    I.fare = (a, b) => fareKm(Math.abs(stById[a].km - stById[b].km));
