    const minOfDay = () => ((host.now() % 1440) + 1440) % 1440;
    const isPeak = (m) => host.isWorkday() && R.peak.some(([a, b]) => m >= a && m < b);
    const headway = (m) => (m >= R.late_after ? R.headway_min.late : isPeak(m) ? R.headway_min.peak : R.headway_min.normal);
