      items.push({ label: "问询：首末班车", act: () => { S.menu = null; const s = stById[S.W.A.station]; toast(`客服：${R.line.name}运营 ${R.hours.label}，本站末班车约 ${hhmm(R.hours.last_train - (stations[stations.length - 1].min - s.min))}（往槐北新村）`, 3.5); } });
