    I.journeyTicketDestination=dest=>{if(!S.menu?.title.startsWith('自助售票机'))return false;const list=stations.filter(s=>s.id!==S.W.A.station),i=list.findIndex(s=>s.id===dest);if(i<0)return false;pickMenu(i);return true;};
