    const w = canvas.width, h = canvas.height, t = SP.tint, n = t.night, tn = st.time, clear = CK.weather === "clear" ? 1 : 1 - CK.intensity;
    const warm = (tn === "afternoon" ? 0.55 : tn === "dusk" ? 0.45 : 0) * clear;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
