      g.addColorStop(0, `rgba(255,196,120,${0.55 * warm})`); g.addColorStop(0.55, `rgba(255,214,160,${0.18 * warm})`); g.addColorStop(1, `rgba(70,80,130,${0.35 * warm})`);
      ctx.fillStyle = g; ctx.fillRect(0, 0, w, h); ctx.restore();
