    for (let k = 0; k < 42 - lead; k++) { const day = first + k, dd = R.date(day * 1440); if (k > 0 && dd.d === 1) break; const c = text('span', String(dd.d ?? k + 1), grid); c.className = (day === today ? 'today' : '') + (marks.has(day) ? ' mark' : '') + (dd.off ? ' off' : ''); }
