 const PHONE_SIDE={SW:-1,S:-1,SE:0,E:1,NE:1,N:-1,NW:0,W:1},PHONE_FACE={SE:1,NW:-1};
 // [shoulder x, ear x] relative to the head centre; y offsets are from the head top.
 const PHONE_GEO={SW:[-8,-7],S:[-7,-5],SE:[-1,-2],E:[7,5],NE:[8,7],N:[-7,-5],NW:[1,2],W:[7,5]};
 function phoneLift(s){const p=clamp(s?.progress);return p<.15?p/.15:p>.85?(1-p)/.15:1;}
 // keypoints for a lift stage: 0 phone in the hanging hand, 1 forearm rising, 2 handset at the ear
 function phoneKeys(dir,stage,hx=0,top=-73){const g=PHONE_GEO[dir]||PHONE_GEO.SW,s=PHONE_SIDE[dir]??-1,f=PHONE_FACE[dir]||0,o=s||f,sh=[hx+g[0],top+21];let el,hd;
  if(stage>=2){el=[sh[0]+o*2,top+31];hd=[hx+g[1],top+15];}
  else if(stage>=1){el=[sh[0]+o*2,top+31];hd=[(sh[0]+hx+g[1])/2+o*(s?3:4),top+23];}
  else{el=[sh[0]+o,top+31];hd=[sh[0]+o*(s?1:2),top+40];}
  return {shoulder:sh,elbow:el,wrist:hd};}
 // Continuous pose (used for culling bounds and tests); drawing snaps to the three pixel stages.
 function phonePose(a,s){const l=phoneLift(s),k0=phoneKeys(a.dir,0),k1=phoneKeys(a.dir,1),k2=phoneKeys(a.dir,2),mix=(p,q,t)=>[p[0]+(q[0]-p[0])*t,p[1]+(q[1]-p[1])*t],pick=n=>l<.5?mix(k0[n],k1[n],l*2):mix(k1[n],k2[n],l*2-1);return {shoulder:pick('shoulder'),elbow:pick('elbow'),wrist:pick('wrist'),lift:l};}
 const hex=(r,g,b)=>'#'+[r,g,b].map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('');
 const rgb=c=>{const n=parseInt(String(c).slice(1,7),16);return Number.isFinite(n)?[n>>16&255,n>>8&255,n&255]:[120,120,120];};
 const shade=(c,k)=>{const [r,g,b]=rgb(c);return k>=1?hex(r+(255-r)*(k-1),g+(255-g)*(k-1),b+(255-b)*(k-1)):hex(r*k,g*k,b*k);};
 const outlineOf=c=>{const [r,g,b]=rgb(c);return hex(r*.3+12,g*.28+10,b*.3+16);};
