 function householdTransaction(actorId,kind,item,cents,commitOther){if(!IDS.includes(actorId)||typeof commitOther!=='function'||!(kind==='spoil'&&['bread','drink'].includes(item)&&cents===0||kind==='appliance'&&item===null&&Number.isSafeInteger(cents)&&cents>0&&cents<=1000000))return{ok:false};const s=state(),r=s.residents[actorId];if(s.receipts.length>=CAP-personalReserved(s)||kind==='spoil'&&r.items[item]<1||kind==='appliance'&&r.walletCents<cents)return{ok:false};const staged=copy(s),q=staged.residents[actorId],receipt={id:staged.nextReceiptId++,actorId,kind,item,cents,at:now(),from:actorId,to:kind==='spoil'?'spoiled':'appliance_coop',storeReceiptId:null,homeKind:null,homeReceiptId:null,homeCostCents:null,homeRefundCents:null};let dropMeal=false;if(kind==='spoil'){q.items[item]--;const meal=q.homeMeal;if(meal&&['walking','active'].includes(meal.stage)&&meal.item===item&&q.items[item]<1&&q.phase==='home_dining'){meal.stage='skipped';meal.lastAt=now();q.phase='home_dining_return';q.index=0;dropMeal=true;}}else q.walletCents-=cents;staged.lastAt=Math.max(staged.lastAt,now());staged.receipts.push(receipt);if(!prepare(staged,now()))return{ok:false};let ok=false;try{ok=commitOther(receipt)===true;}catch{}if(!ok)return{ok:false};if(kind==='spoil'){r.items[item]=q.items[item];if(dropMeal){r.homeMeal=q.homeMeal;r.phase=q.phase;r.index=q.index;plans.delete(r.id);}}else r.walletCents=q.walletCents;s.lastAt=staged.lastAt;s.receipts=staged.receipts;s.nextReceiptId=staged.nextReceiptId;return{ok:true,receiptId:receipt.id};}
 function studioPayment(r,event,commitEmployer){const s=state();if(s.residents[r?.id]!==r||r.area!=='community_workspace_room'||Math.hypot(r.x-6.4,r.y-.95)>.22||event?.kind!=='paid'||event.actorId!==r.id||event.at!==now()||s.receipts.length>=CAP-personalReserved(s)||s.receipts.some(p=>p.kind==='studio_wage'&&p.storeReceiptId===event.id))return false;const n=copy(s),q=n.residents[r.id];q.walletCents+=8000;n.lastAt=now();n.receipts.push({id:n.nextReceiptId++,actorId:r.id,kind:'studio_wage',item:null,cents:8000,at:now(),from:'merchant_coop',to:r.id,storeReceiptId:event.id,homeKind:null,homeReceiptId:null,homeCostCents:null,homeRefundCents:null});if(!prepare(n,now())||commitEmployer(n)!==true)return false;r.walletCents=q.walletCents;s.receipts=n.receipts;s.nextReceiptId=n.nextReceiptId;s.lastAt=n.lastAt;return true;}
