 function forceHeld(id){const a=SP.actors?.list?.find(a=>a.id===id)||actors.get(id),p=G.ps?.npcConflict?.people?.[id];return !!(a?.dead||a?.injured||a?.restrained||p&&(p.health<100||p.restrained||typeof p.mode==='string'&&p.mode!=='calm'));}
