 function indoorPolys(area,A=sceneData(area)){if(!A)return [];let cache=geometry.get(area);if(!cache||cache.source!==A){cache={source:A,doors:A.objects.filter(o=>o.block),signature:null,polys:[]};geometry.set(area,cache);}const signature=cache.doors.map(o=>o.id+':'+(SP.place?.istate?.[area]?.[o.id]??o.state)).join('|');if(cache.signature!==signature){const polys=[];for(const o0 of A.objects){const o={...o0,rot:o0.rot||0,state:SP.place?.istate?.[area]?.[o0.id]??o0.state},p=SP.K?.pieces?.[o.type];if(o.block&&o.state!=='open'){const [x0,y0,x1,y1]=o.block;polys.push([[x0,y0],[x1,y0],[x1,y1],[x0,y1]]);}if(!p||p.layer!=='sorted'||o.on_roof)continue;const st=o.state||p.states[0],rects=(p.footprint_states&&st in p.footprint_states?p.footprint_states[st]:p.footprint)||[];for(const rect of rects)polys.push(SP.footPoly(rect,o.rot,o.x,o.y));}for(const c of A.colliders||[]){const [x0,y0,x1,y1]=c.rect;polys.push([[x0,y0],[x1,y0],[x1,y1],[x0,y1]]);}cache.signature=signature;cache.polys=polys;}return cache.polys;}
 // Snapshot live shapes once per bounded search, not once per explored node.
 // Static clearance stays .25; actor clearance uses the actual mover + Actor GAP.
 function liveActorShapes(r){
  const a=actors.get(r.id);if(r.area!==current()||SP.metroActive||SP.cbd?.active||!a||!SP.actors.list.includes(a))return null;
  const circles=[];for(const b of SP.actors.list){if(b===a||b.hidden||(b.level||'')!==(a.level||''))continue;for(const c of b.circles?.()||[])circles.push(c.slice());}
  return {circles,mover:(a.circles?.()||[[a.x,a.y,a.radius??.22]]).map(([x,y,rad])=>[x-a.x,y-a.y,rad])};
 }
 function blocked(area,x,y,radius=.25,resident,context){
  if(area==='street'){
   if(current()==='street'&&!SP.metroActive&&!SP.cbd?.active){if(W.blockedStatic?.(x,y,radius))return true;for(const car of context?.cars??SP.traffic?.allCars?.()??[])if(car.poly&&SP.circlePoly?.(x,y,radius,car.poly))return true;}
   else{const b=SP.place?.street;if(!b?.data?.bounds||!b.colliders||!b.cgrid)return true;const B=b.data.bounds;if(x-radius<B.x0||x+radius>B.x1||y-radius<B.y0||y+radius>B.y1)return true;const seen=new Set();for(let a=Math.floor((x-radius)/2);a<=Math.floor((x+radius)/2);a++)for(let v=Math.floor((y-radius)/2);v<=Math.floor((y+radius)/2);v++)for(const n of b.cgrid.get(a*1000+v)||[])seen.add(n);for(const n of seen){const c=b.colliders[n];if(!c.roof&&SP.circlePoly(x,y,radius,c.poly))return true;}if(SP.storeSupply?.offscreenObstacles?.()?.some(o=>o.poly?SP.circlePoly(x,y,radius,o.poly):Math.hypot(o.x-x,o.y-y)<radius+o.r))return true;}
  }else{
   const A=sceneData(area);if(!A)return true;const B=Array.isArray(A.bounds)?A.bounds:[A.bounds.x0,A.bounds.y0,A.bounds.x1,A.bounds.y1];if(x-radius<B[0]||x+radius>B[2]||y-radius<B[1]||y+radius>B[3])return true;
   if(area==='store_24'||area==='store_24_staff'||area==='community_workspace_room'||area.startsWith('shared_home_')){
    if(current()===area){if(W.blockedStatic?.(x,y,radius))return true;}else{const polys=context?.indoorPolys??indoorPolys(area,A);if(polys.some(p=>SP.circlePoly(x,y,radius,p)))return true;}
   }else{for(const c of A.colliders||[]){const b=c.rect;if(Math.hypot(Math.max(b[0]-x,0,x-b[2]),Math.max(b[1]-y,0,y-b[3]))<radius)return true;}for(const g of A.gates||[])if((!resident?.secured||!resident.ticket)&&Math.hypot(Math.max(g.flap[0]-x,0,x-g.flap[2]),Math.max(g.flap[1]-y,0,y-g.flap[3]))<radius)return true;for(const a of context?.metroActors??root.FushiMetro?.stableAreaActors?.(area)??[])if(a.id!==resident?.id&&Math.hypot(a.x-x,a.y-y)<radius+a.r)return true;}
  }
  if(context?.liveActors){for(const [ox,oy,rad] of context.liveActors.mover)for(const [bx,by,br] of context.liveActors.circles)if(Math.hypot(x+ox-bx,y+oy-by)<rad+br+.004)return true;return false;}
  for(const q of context?.residents??Object.values(state().residents))if(q.id!==resident?.id&&q.area===area&&Math.hypot(q.x-x,q.y-y)<radius+.22)return true;return false;
 }
 // Same authored/cached street geometry as movement, without the two speakers' own circles.
 function recruitmentSight(a,b){if(!a||!b||state().residents[a.id]!==a||state().residents[b.id]!==b||a===b||a.area!=='street'||b.area!=='street'||Math.hypot(a.x-b.x,a.y-b.y)>2.25)return false;
  for(const r of [a,b])if(!['park_loop','park_rest','day_rest'].includes(r.phase)||r.needs.energy<=35||forceHeld(r.id)||SP.cityIncidents?.holdsActor?.(r.id)||SP.npcConversations?.holdsActor?.(r.id)||SP.socialFlow?.attending?.(r.id)||SP.employment?.reportFor?.(r)||r.dailyPlan&&now()>=r.dailyPlan.returnAt-(SP.residentMemory?.policyFor?.(r)?.returnEarlierMinutes||0))return false;
  const saved=SP.place?.street,data=current()==='street'?W.data:saved?.data;if(!data?.bounds)return false;for(const r of [a,b]){for(const lane of data.traffic?.lanes||[]){const v=lane.axis==='x'?r.y:r.x,u=lane.axis==='x'?r.x:r.y;if(Number.isFinite(lane.c)&&Array.isArray(lane.range)&&u>=lane.range[0]-.3&&u<=lane.range[1]+.3&&Math.abs(v-lane.c)<=1.8)return false;}for(const c of data.traffic?.crosswalks||[])if(r.x>=c.x0-.3&&r.x<=c.x1+.3&&r.y>=c.y0-.3&&r.y<=c.y1+.3)return false;}
  const steps=Math.max(1,Math.ceil(Math.hypot(a.x-b.x,a.y-b.y)/.1));for(let i=0;i<=steps;i++){const x=a.x+(b.x-a.x)*i/steps,y=a.y+(b.y-a.y)*i/steps;if(current()==='street'){if(W.blockedStatic?.(x,y,.05))return false;}else{if(!saved?.colliders||!saved.cgrid||x<data.bounds.x0||x>data.bounds.x1||y<data.bounds.y0||y>data.bounds.y1)return false;const seen=new Set();for(let ix=Math.floor((x-.05)/2);ix<=Math.floor((x+.05)/2);ix++)for(let iy=Math.floor((y-.05)/2);iy<=Math.floor((y+.05)/2);iy++)for(const n of saved.cgrid.get(ix*1000+iy)||[])seen.add(n);for(const n of seen){const c=saved.colliders[n];if(!c.roof&&SP.circlePoly(x,y,.05,c.poly))return false;}}for(const car of SP.traffic?.allCars?.()||[])if(car.poly&&SP.circlePoly?.(x,y,.05,car.poly))return false;}return true;
 }
 function makeActor(r){let a=actors.get(r.id);if(!a&&SP.Actor){const p=PROFILES[r.id];a=new SP.Actor({id:r.id,set:p.set,x:r.x,y:r.y,radius:.22,speed:1.3,name:p.name});a.dailyResident=true;a.setDir?.(r.dir);SP.ensureActor?.(p.set);actors.set(r.id,a);}return a;}
