 function regularTerms(id,day=Math.floor(now()/1440),ps=G.ps){const s=ps?.employment,v=s&&M.replay(s,now()),q=v?.regular.contracts.filter(q=>q.actorId===id&&q.hireEventId===s.events.filter(e=>e.actorId===id&&e.kind==='hired').at(-1)?.id).at(-1);return v?.holder===id&&q&&day>=q.firstDay&&!v.workforce?.offDay(id,day)?{...copy(q),day,startAt:day*1440+540,endAt:day*1440+780,maxMinutes:240,rateCents:1500}:null;}
