 function regularProof(ps,s,at){const v=M.replay(s,at);if(!v)return false;for(const c of v.regular.contracts){const e=s.events[c.id-1],q=s.shifts.find(q=>q.id===e.sourceId),r=ps?.routineWork?.records?.find(r=>r.id===q?.routineId);if(!r||r.status!=='completed'||r.finishedAt>c.signedAt||r.workedMinutes<29.999999||s.shifts.some(q=>q.actorId===c.actorId&&q.assignedAt<=c.signedAt&&q.endAt>c.signedAt))return false;}for(const q of v.regular.records){const key='npc:'+q.actorId+':'+q.day;if(q.closedAt===null){if(ps?.neighborhoodStore?.npcWageShifts?.[q.actorId]!==key)return false;}else{const c=ps?.neighborhoodStore?.wageClaims?.find(c=>c.id===q.claimId);if(!c||c.employeeId!==q.actorId||c.shiftKey!==key||c.earnedAt!==q.closedAt||c.owedCents!==Math.floor(q.minutes*1500/60))return false;}}return true;}
 function termsCandidate(id){const s=G.ps?.employment,v=s&&M.replay(s,now());if(v?.holder!==id||v.regular.contracts.some(q=>q.actorId===id&&q.hireEventId===s.events.filter(e=>e.kind==='hired'&&e.actorId===id).at(-1)?.id))return null;const hire=s.events.filter(e=>e.kind==='hired'&&e.actorId===id).at(-1),rows=s.shifts.filter(q=>q.actorId===id&&q.hireEventId===hire.id);if(!rows.length||rows.length>=3||rows.some(q=>q.endAt>now()))return null;const q=rows.at(-1),r=G.ps.routineWork?.records?.find(r=>r.id===q.routineId);return r?.status==='completed'&&r.workedMinutes>=29.999999?copy(q):null;}
