 function normalProof(ps,s,e){const hire=s.events.filter(q=>q.id<e.id&&q.kind==='hired'&&q.actorId===e.actorId).at(-1),rows=s.shifts.filter(q=>q.actorId===e.actorId&&q.hireEventId===hire?.id&&q.assignedAt<=e.at);if(rows.length<3||rows.at(-1).id!==e.sourceId)return false;const completed=rows.filter(q=>{const r=ps?.routineWork?.records?.find(r=>r.id===q.routineId);return r?.status==='completed'&&r.finishedAt<=e.at&&r.workedMinutes>=29.999999&&r.wageReceiptId!==null&&ps?.neighborhoodStore?.wageClaims?.some(c=>c.id===r.wageReceiptId&&c.employeeId===e.actorId&&c.owedCents===Math.floor(r.workedMinutes*r.rateCents/60));});return completed.length>=3&&completed.at(-1).id===e.sourceId&&!rows.some(q=>{const r=ps?.routineWork?.records?.find(r=>r.id===q.routineId);return r&&['planned','working'].includes(r.status);});}
