 function ledgerAt(st){const R=st?.receipts||[],tillAt=q=>{let t=st.opening?.tillCents||0;for(let i=0;i<q;i++){const r=R[i];if(r.kind==='purchase')t+=r.totalCents;else if(['return','wholesale','wage_payment'].includes(r.kind))t-=r.totalCents;}return t;},unpaidAt=(q,id=null)=>{let n=0;for(let i=0;i<q;i++){const r=R[i];if(id&&r.buyerId!==id)continue;if(r.kind==='wage_accrual')n+=r.totalCents;else if(r.kind==='wage_payment')n-=r.totalCents;}return n;};return {R,tillAt,unpaidAt,exact:tillAt(R.length)===st?.tillCents};}
 function ledgerBasis(ps=G.ps){const st=ps?.neighborhoodStore;if(!st)return {basisSequence:0,availableCents:0};const L=ledgerAt(st),q=L.R.length,till=L.exact?L.tillAt(q):st.tillCents;return {basisSequence:q,availableCents:Math.max(0,till-L.unpaidAt(q))};}
