 function prepare(s,at=now(),ps=G.ps){const n=M.prepare(s,at),daily=ps?.npcDailyLife?.blocks?SP.npcDailyLife?.prepare?.(ps.npcDailyLife,at):ps?.npcDailyLife,pays=n?.studio.events.filter(e=>e.kind==='paid')||[],personal=daily?.receipts?.filter(e=>e.kind==='studio_wage')||[];if(pays.length!==personal.length||pays.some(e=>personal.filter(p=>p.actorId===e.actorId&&p.storeReceiptId===e.id&&p.at===e.at&&p.cents===8000).length!==1))return null;return n&&dutyProof(ps,n)&&regularProof(ps,n,at)&&workforceProof(ps,n,at)&&n.events.every(e=>(e.kind!=='resigned_unpaid'||proof(ps,e))&&(e.kind!=='resigned_normal'||normalProof(ps,n,e)))&&n.shifts.every(q=>{const r=ps?.routineWork?.records?.find(r=>r.id===q.routineId);return r&&r.actorId===q.actorId&&r.sleptAt===q.assignedAt&&r.startAt===q.startAt&&r.endAt===q.endAt;})?n:null;}
 function state(){if(!G.ps.employment)G.ps.employment=fresh();return G.ps.employment;}
