 function propose(actors){if(!Array.isArray(actors)||actors.length!==2||!recruitmentPair(...actors))return null;const s=G.ps.employment,v=s&&M.replay(s,now());if(!v||s.events.length>=M.CAP-2)return null;for(const speaker of actors){const listener=actors.find(a=>a!==speaker),source=s.events.filter(e=>e.actorId===speaker.id&&v.notices[e.id]).at(-1),f=source&&v.notices[source.id],known=Math.max(v.seen[listener.id]?.revision||0,v.heard[listener.id]?.revision||0);if(!f||f.revision<=known||f.revision<(v.heard[speaker.id]?.revision||0))continue;const text='我在'+stamp(f.at)+'亲自问过便利店柜台，第'+f.revision+'版'+(f.vacant?'有一个预约名额':'已经满员')+'。之后可能变化，应聘还得自己去确认。',token={};recruitmentTokens.set(token,{owner:G.ps,speaker,listener,sourceId:source.id,text});return{topic:'便利店招聘消息',employmentToken:token,lines:[{speaker:speaker.id,text},{speaker:listener.id,text:'我记下时间和出处了，有空会去柜台核对，不把这条消息当录用保证。'}]};}return null;}
