 const open=G.openMenu;if(open)G.openMenu=function(o,options){const id=o?.actor?.id||o?.id,a=SP.actors?.list?.find(a=>a.id===id),owner=G.ps;if(M.IDS.includes(id)&&Array.isArray(options)&&!options.some(q=>q.id==='employment_history'))options=options.concat({id:'employment_history',label:'现在做什么工作？应聘顺利吗？',ok:!!pair(a),fn:()=>{if(owner!==G.ps||!pair(a))return '请重新走近可交谈的本人。';const t=describe(id);if(SP.residentMemoryUI?.open?.(id,'career',t))return null;return t;}});if(id==='counter'&&Array.isArray(options)&&!options.some(q=>q.id==='employment_notice'))options=options.concat({id:'employment_notice',label:'查看预约店务招聘启事',ok:SP.place?.where?.()==='store_24'&&Math.hypot((SP.player?.x||0)-point[0],(SP.player?.y||0)-point[1])<2.6,fn:()=>{if(owner!==G.ps||SP.place?.where?.()!=='store_24'||Math.hypot(SP.player.x-point[0],SP.player.y-point[1])>=2.6)return '请走近店内柜台。';const v=M.replay(state(),now());return v?'预约店务岗位：'+(v.holder?'已满员':'空缺1名')+'；招聘第'+v.revision+'版。每天最多30分钟，沿用店内当日小时报价，实际到岗计工、柜台付款；这不是全日制收入保证。实际完成试做班的在任居民可当面确认次日起09:00—13:00持续任职条款，15元/小时、最高实际60元；同一名额，有限门店款付款，临时支援另行结算。':'岗位记录暂时无法核对。';}});return open.call(this,o,options);};
