/* Actual resident stock handling: one shared finite cargo slot, real staff doorway and shelf routes. */
(function(root){'use strict';const SP=root.SP,G=SP?.game,M=root.NeighborhoodStoreModel;if(!G||!M)return;const MAIN='store_24',BACK='store_24_staff',DOOR=[7.5,5.4],PICK=[1.95,2.05],EXIT=[.42,1.5],SHELVES={bread:[2.8,3.42],drink:[3.1,4.95]},STREET_DOOR=[37,3.55],INNER_DOOR=[[4.5,1],[4.5,.42]],JOB={daily_wen:[1.1,2.3],daily_shen:[5.4,4.4]},now=()=>SP.clock.abs(),copy=x=>JSON.parse(JSON.stringify(x));
 const box=id=>SP.neighborhoodStore.cargoFor(id),phase=(r,p,t)=>{r.phase=p;r.index=0;r.waitUntil=null;t.forget();};
 function item(s){return ['bread','drink'].find(id=>s.stock[id]<=8&&s.backroom[id]>0)||null;}
 function needsOrder(s){return (!SP.workforce||SP.workforce.procureCap()>0)&&SP.storeSupply&&G.ps.storeSupply?.phase!=='enroute'&&!s.pendingDelivery&&['bread','drink'].some(k=>s.stock[k]<=8&&s.backroom[k]===0&&s.supplierStock[k]>0&&s.tillCents-s.wageClaims.reduce((n,c)=>n+c.owedCents-c.paidCents,0)>=M.WHOLESALE_PRICES[k])&&SP.storeSupply.snapshot().phase==='idle';}
 function transfer(r,kind,itemId){const before=G.ps.neighborhoodStore,next=M.prepare(before,now());if(!next)return false;const c=box(r.id),args={employeeId:r.id,at:now(),expectedSequence:next.nextReceiptId-1,...(kind==='pickup'?{item:itemId,quantity:Math.min(8,16-next.stock[itemId],next.backroom[itemId]),taskId:'npc-duty:'+r.id+':'+next.nextReceiptId}:{taskId:c?.taskId})},z=M[kind==='restock'?'deliver':kind](next,args);if(!z.ok)return false;G.ps.neighborhoodStore=next;if(!SP.employment.commitDuty(r,z.receipt).ok){G.ps.neighborhoodStore=before;return false;}return true;}
 function step(r,dt,t){const stockPhase=r.phase.startsWith('job_stock_'),terms=SP.employment?.regularTerms?.(r.id,r.job?.day);if(!terms||r.job?.status!=='working'||!stockPhase&&r.phase!=='job_work')return false;const at=now(),end=terms.endAt,s=G.ps.neighborhoodStore;if(!s)return false;
  if(!stockPhase){if(r.area===MAIN&&at<end-5&&SP.storeSupply?.residentOrderFor?.(r.id)&&G.ps.employment.events.length<root.EmploymentModel.CAP-12)phase(r,'job_stock_receive_out',t);else{if(r.area!==MAIN||(!item(s)&&!needsOrder(s))||s.cargo||at>=end-20||G.ps.employment.events.length>=root.EmploymentModel.CAP-12||s.receipts.length+M.reservedSlots(s)>=M.MAX_RECEIPTS-6)return false;phase(r,'job_stock_in',t);}}
  const elapsed=at<=end+.000001?Math.max(0,Math.min(dt,end-Math.max(r.job.lastAt??at,at-dt))):0;r.job.lastAt=at;const count=()=>{if(elapsed>0&&SP.employment.regularTick(r,Math.min(elapsed,240-r.job.workedMinutes)).ok){r.job.workedMinutes=Math.min(240,r.job.workedMinutes+elapsed);if(r.job.workedMinutes>=239.999999)r.job.workedMinutes=240;}};
  const walk=p=>{const done=t.walk(r,p,dt);if(t.moved()>0)count();return done;};
  /* Site85 local WORK-014: the ordering employee physically walks out to the street, signs in person, then walks back to the post. */
  const mine=()=>{const p=G.ps.neighborhoodStore?.pendingDelivery;return !!p&&G.ps.neighborhoodStore.receipts[p.id-1]?.buyerId===r.id;};
  if(r.phase==='job_stock_receive_out'){if(at>=end||!mine()){phase(r,'job_stock_return',t);return true;}if(!walk(INNER_DOOR[Math.min(r.index,1)]))return true;if(r.index===0){r.index=1;t.forget();return true;}t.transition(r,'street',STREET_DOOR,'job_stock_receive_meet');return true;}
  if(r.phase==='job_stock_receive_meet'){if(at>=end||!mine()){phase(r,'job_stock_receive_back',t);return true;}if(!walk(SP.storeSupply.MEET))return true;if(G.ps.storeSupply?.phase!=='waiting'){r.waitUntil=null;return true;}if(r.waitUntil===null)r.waitUntil=at+1;if(at<r.waitUntil){count();return true;}if(SP.storeSupply.residentReceive(r).ok)phase(r,'job_stock_receive_back',t);return true;}
  if(r.phase==='job_stock_receive_back'){if(walk(STREET_DOOR))t.transition(r,MAIN,INNER_DOOR[0],'job_stock_return');return true;}
  if(r.phase==='job_stock_in'){if(at>=end&&!box(r.id)){phase(r,'job_stock_return',t);return true;}if(walk(DOOR))t.transition(r,BACK,[.95,1.5],'job_stock_pick');return true;}
  if(r.phase==='job_stock_pick'){if(!walk(PICK))return true;if(at>=end){if(box(r.id)&&!transfer(r,'cancel'))return true;phase(r,'job_stock_out',t);return true;}if(!box(r.id)&&!item(s)&&needsOrder(s)){if(r.waitUntil===null)r.waitUntil=at+2;count();if(at>=r.waitUntil){SP.storeSupply.residentOrder(r);phase(r,'job_stock_out',t);}return true;}if(s.cargo&&!box(r.id)||!box(r.id)&&!item(s)){phase(r,'job_stock_out',t);return true;}if(box(r.id)){phase(r,'job_stock_out',t);return true;}if(r.waitUntil===null)r.waitUntil=at+2;count();if(at>=r.waitUntil){const chosen=item(G.ps.neighborhoodStore);if(chosen&&transfer(r,'pickup',chosen))phase(r,'job_stock_out',t);}return true;}
  if(r.phase==='job_stock_out'){if(at>=end&&box(r.id)){phase(r,'job_stock_pick',t);return true;}if(walk(EXIT)){const carrying=!!box(r.id);t.transition(r,MAIN,[7.4,5.4],carrying?'job_stock_shelf':'job_stock_return');}return true;}
  if(r.phase==='job_stock_shelf'){const cargo=box(r.id);if(!cargo){phase(r,'job_stock_return',t);return true;}if(at>=end){phase(r,'job_stock_in',t);return true;}if(cargo.item==='bread'&&r.index===0){if(walk([4.25,3.25])){r.index=1;t.forget();}return true;}if(!walk(SHELVES[cargo.item]))return true;if(r.waitUntil===null)r.waitUntil=at+2;count();if(at>=r.waitUntil&&transfer(r,'restock'))phase(r,'job_stock_return',t);return true;}
  if(r.phase==='job_stock_return'){if(box(r.id)){phase(r,'job_stock_in',t);return true;}if(walk(JOB[r.id]))phase(r,'job_work',t);return true;}return false;
 }
 function speechFor(r){return {job_stock_in:box(r.id)?'这箱还没卸货，先带回员工室，不把货凭空丢掉。':'货架余量低，去员工室领有限后仓的货。',job_stock_pick:'在员工室核对后仓，缺货时用门店可用款订货；到货前不能上架。',job_stock_out:box(r.id)?'抱好本人的货箱，走回店内对应货架。':'领货结束，走回店里继续原工作。',job_stock_shelf:'把这箱货实际搬到对应货架，卸下后顾客才买得到。',job_stock_return:'补货处理完，回原工位；工资仍按实际履职时间。',job_stock_receive_out:'送货车到了，这单是我下的，出店去街面当面接货。',job_stock_receive_meet:'在店门口和送货员当面点清，签收后才算进后仓。',job_stock_receive_back:G.ps?.neighborhoodStore?.pendingDelivery?'这单还没接成，先回店里，货不会凭空入仓。':'货已签收进后仓，回店接着上架。'}[r.phase]||null;}
 SP.storeDuties={step,speechFor};
})(window);

