 function activeContract(id,at=now()){return contracts(at).find(c=>c.actorId===id&&c.signedAt<=at&&(c.endAt===null||at<c.endAt))||null;}
 function works(c,day,w){return day>=c.firstDay&&!w.offDay(c.actorId,day);}
