 function note(e){spoken.set(e.kind+':'+(e.subjectId||e.actorId),{at:now(),e:copy(e)});try{SP.lifeChronicle?.record?.('workforce_'+e.kind,'store_24',describeEvent(e),{eventId:e.id});}catch{}}
 /* ---- A. owner presence and daily plan ---- */
