 function ensurePlan(at=now()){const x=view(at);if(!x)return null;const day=dayOf(at),p=x.w.plans[day];if(p)return p;const staffed=staffedToday(at),h=WF.hours(staffed),m=at-day*D;if(m<h[0]||m>=h[1]||at<x.w.startedAt)return null;const b=SP.employment.ledgerBasis(),r=commit({kind:'owner_plan',actorId:OWNER,data:{day,openFrom:h[0],openTo:h[1],staffed,procureCap:WF.capFrom(b.availableCents,300),basisSequence:b.basisSequence,availableCents:b.availableCents}});return r.ok?r.event:null;}
