 function jobsFor(id,at=now()){const out=[],x=view(at),c=activeContract(id,at);if(c){const n=x.w.openNotice(c.id),rest=x.w.rests[c.id];out.push({employerId:'store_24',employer:'街坊便利店（周店长）',ledger:'neighborhoodStore',hours:'每天09:00—13:00',restWeekday:rest?rest.data.weekday:null,notice:n?{by:n.data.by,effectiveAt:n.data.effectiveAt}:null});}const q=SP.studioWork?.activeFor?.(id);if(q)out.push({employerId:'studio2',employer:'商户合作社',ledger:'employment.studio',hours:'项目制，门店班外09:00—20:00',minutes:q.minutes,status:q.status});return out;}
