 function speechFor(r){const at=now(),need=counterNeed(r,at);if(['street_store','browse','counter'].includes(r.phase)&&need)return {appeal:'店长说我无故缺勤要辞退我，我去柜台当面申辩，拿请假记录说话。',handover:'辞退/辞职通知到期了，去柜台和周店长当面交接，欠我的工资照旧记着。',resign:'工资拖欠超过一天，去柜台跟店长递交三天辞职通知，通知期照常上班。'}[need];const n=myNotice(r.id);if(n&&r.phase==='job_work')return '通知期内照常上班，'+stamp(n.data.effectiveAt)+'后去柜台交接。';const x=view(at),c=x&&activeContract(r.id,at);if(c&&!works(c,dayOf(at),x.w)&&dayOf(at)>=c.firstDay&&at%D>=480&&at%D<780&&r.area==='street')return x.w.approvedFor(r.id,dayOf(at),at)?'今天请过假，店长批了，不去店里；这天不算工时也不领工资。':'今天是我的每周休息日，店里由周店长顶班。';if(String(r.phase).startsWith('home_')&&spoken.get('leave_request:'+r.id)&&at-spoken.get('leave_request:'+r.id).at<5)return '给周店长打电话请明天的假，身体不太舒服；批不批要看店长。';return null;}
 const visit0=SP.employment.visit,seek0=SP.employment.seekExit,speech0=SP.employment.speechFor,describe0=SP.employment.describe;
