function leased(o){try{return !!SP.sharedHome?.status?.(o,now())?.lease;}catch{return false;}}
function held(o,item,p=ps()){if(o==='player')return Math.max(0,Math.floor(Number(p?.items?.[item])||0));const n=p?.npcDailyLife?.residents?.[o]?.items?.[item];return Number.isSafeInteger(n)&&n>0?n:0;}
function seed(at,p=ps()){const s=M.fresh(at),daily=p?.npcDailyLife?.blocks?SP.npcDailyLife?.prepare?.(p.npcDailyLife,at):p?.npcDailyLife;for(const o of M.OWNERS)for(const k of M.FOODS[o]){const n=o==='player'?held(o,k,p):Math.max(0,daily?.residents?.[o]?.items?.[k]||0);const store=o!=='player'&&daily?.residents?.[o]?.area==='shared_home_flat'?'room':'carried';for(let i=0;i<n;i++)M.addFood(s,o,k,at,store);}return s;}
function fresh(at=now()){return seed(at);}
function state(){if(!ps())return null;if(!ps().household)ps().household=seed(now());if(lastPs!==ps()){lastPs=ps();resetRuntime();}return ps().household;}
function note(msg){if(msg&&msg!==lastNote){lastNote=msg;try{W?.logEvent?.(msg);}catch{}}return msg;}
function bubble(id,text){const a=SP.actors?.list?.find(a=>a.id===id&&!a.hidden);if(a)a.bubble={t:3.2,text};}
function think(o,text){thought[o]={at:now(),text};bubble(o,text);}
/* 1. food units follow real holdings; resident consumption is read from their own receipts */
function sync(s,at){const daily=ps().npcDailyLife,eaten={daily_wen:{bread:0,drink:0},daily_shen:{bread:0,drink:0}};
 if(daily?.receipts){for(const r of daily.receipts)if(r.id>=seen&&r.kind==='consume'&&eaten[r.actorId]&&r.item in eaten[r.actorId])eaten[r.actorId][r.item]++;seen=daily.nextReceiptId;}
 for(const o of M.OWNERS){const home=atHome(o);for(const k of M.FOODS[o]){let have=s.food.filter(r=>r.owner===o&&r.item===k).length;const want=held(o,k);
  while(have>want){M.takeFood(s,o,k,at);have--;if(o==='player'||eaten[o][k]>0){if(o!=='player')eaten[o][k]--;M.trashAdd(s,o,home,1);}}
  while(have<want){if(!M.addFood(s,o,k,at,home?M.homeStorage(s,o,leased(o),where(o)):'carried'))break;have++;}}
  if(home){const lease=leased(o),place=where(o);for(const r of s.food.filter(r=>r.owner===o&&r.storage==='carried'))M.moveFood(r,M.homeStorage(s,o,lease,place),at);}}}
/* 2. discovery: in hand at once, at home only after actually being back in the flat */
function discover(s,at){for(const o of M.OWNERS){const home=atHome(o),place=where(o),rows=s.food.filter(r=>r.owner===o&&M.spoiled(r,at)&&(r.storage==='carried'||M.PLACE_OF[r.storage]===place));if(!rows.length)continue;const found=[];
  for(const r of rows){if(o==='player'){if(held(o,r.item)<1)continue;ps().items[r.item]--;M.discard(s,r,at,home);found.push(r.item);}else{const z=SP.npcDailyLife?.householdTransaction?.(o,'spoil',r.item,0,()=>{M.discard(s,r,at,home);return true;});if(z?.ok)found.push(r.item);}}
  if(!found.length)continue;const what=[...new Set(found)].map(k=>LABEL[k]).join('、');
  if(o==='player')note(`${home?'回家检查':'翻包发现'}：${what}放坏了，${found.length}件扔进${home?'家里的垃圾袋':'随身垃圾袋'}。`);
  else{const wallet=ps().npcDailyLife.residents[o].walletCents,q=M.reflect(s,o,at,wallet);think(o,q?.plan==='want_fridge'?`又放坏了${what}……一周丢了${q.evidence.length}件，房里没冰箱，攒够钱了，考虑网上买台二手小冰箱。`:q?.plan==='save_money'?`又放坏了${what}。想买个小冰箱，可钱还不够，先少买点。`:`${what}放坏了，可惜。下次少买一点。`);}}}
/* 3. resident App order, only while actually on the phone at home, from their own wallet */
function residentOrders(s,at){for(const o of M.RES){const r=ps().npcDailyLife?.residents?.[o],q=s.reflections.filter(x=>x.owner===o).at(-1);if(!r||q?.plan!=='want_fridge'||at-q.at>M.WEEK||r.phase!=='home_phone'||M.canOrder(s,o)||!leased(o)||r.walletCents<M.PRICE+M.RESERVE)continue;
  const z=SP.npcDailyLife?.householdTransaction?.(o,'appliance',null,M.PRICE,rc=>M.order(s,{buyer:o,channel:'delivery',at,receiptId:rc.id}).ok);if(z?.ok)think(o,'在手机上下单了一台二手小冰箱，60块，约好送货上门。');}}
function inRoom(o){const b=ROOM_BOUNDS[o],x=o==='player'?SP.player?.x:ps().npcDailyLife?.residents?.[o]?.x,y=o==='player'?SP.player?.y:ps().npcDailyLife?.residents?.[o]?.y;return atHome(o)&&x>=b[0]&&x<=b[2]&&y>=b[1]&&y<=b[3];}
/* 4. delivery/pickup/installation: the recipient must really be there */
function fulfil(s,at){for(const o of s.orders){if(o.status==='ordered'&&at>=o.readyAt){if(o.channel==='pickup'){o.status='arrived';if(o.buyer==='player')note('二手小冰箱已送到驿站快递柜，请本人去取。');}else if(M.deliveryOpen(at)){if(inBuilding(o.buyer)){o.status='handed';o.handedAt=at;if(o.buyer==='player')note('送货员把二手小冰箱抬进了合租住处，签收了。');else think(o.buyer,'冰箱送到了，签收，搬进房间装好。');}else{const slot=Math.floor(at/120);if(attempts.get(o.id)!==slot){attempts.set(o.id,slot);o.attempts++;if(o.buyer==='player')note('送货员打电话说家里没人，冰箱改约下一个时段再送。');}}}}
  if((o.status==='handed'||o.status==='carried')&&at>=o.handedAt+M.INSTALL&&(o.channel==='pickup'?inRoom(o.buyer):atHome(o.buyer))){if(M.install(s,o,at,leased(o.buyer))){if(o.buyer==='player')note('二手小冰箱在房间里插上电，开始制冷了。房里的食材挪了进去。');else think(o.buyer,'小冰箱装好了，以后面包能多放几天。');}}}}
/* 5. resident trash: take the home bag when leaving, drop at a real bin passed on the street, else bring it back */
function residentTrash(s,at){const daily=ps().npcDailyLife;if(!daily?.residents)return;for(const o of M.RES){const r=daily.residents[o],a=r.area,p=prevArea[o];prevArea[o]=a;
  if(p&&p!==a){if(['shared_home_lobby','shared_home_flat'].includes(p)&&a==='street'&&s.trash.home[o]>0){s.trash.carried[o]+=s.trash.home[o];s.trash.home[o]=0;}
   if(a==='shared_home_flat'&&s.trash.carried[o]>0){s.trash.home[o]+=s.trash.carried[o];s.trash.carried[o]=0;}}
  if(a==='street'&&s.trash.carried[o]>0)for(const [id,b]of Object.entries(M.BINS))if(Math.hypot(r.x-b.x,r.y-b.y)<=2&&M.binSpace(s,id)>0){const k=M.drop(s,o,id,s.trash.carried[o]);if(k)bubble(o,'顺手把垃圾扔进'+b.name+'。');}}}
function cases(s,at){for(const c of s.cases)if(c.status==='reported'&&M.decide(s,c,at))note(`市容通知：街上乱丢垃圾经目击举报核实，罚款50元，请到任一垃圾桶扫码缴纳。`);}
/* 6. sanitation: one walking worker, near and far on the same route and speed */
function streetLive(){return SP.place?.where?.()==='street'&&!SP.metroActive&&!SP.cbd?.active;}
function streetBlocked(x,y,rad){if(streetLive())return !!W?.blockedStatic?.(x,y,rad);const b=SP.place?.street;if(!b?.data?.bounds||!b.colliders||!b.cgrid)return false;const B=b.data.bounds;if(x-rad<B.x0||x+rad>B.x1||y-rad<B.y0||y+rad>B.y1)return true;for(let a=Math.floor((x-rad)/2);a<=Math.floor((x+rad)/2);a++)for(let v=Math.floor((y-rad)/2);v<=Math.floor((y+rad)/2);v++)for(const n of b.cgrid.get(a*1000+v)||[]){const c=b.colliders[n];if(!c.roof&&SP.circlePoly?.(x,y,rad,c.poly))return true;}return false;}
function approach(g){if(!streetBlocked(g.x,g.y,.28))return[g.x,g.y];for(const r of [.6,.8,1,1.2])for(let k=0;k<8;k++){const x=g.x+Math.cos(k*Math.PI/4)*r,y=g.y+Math.sin(k*Math.PI/4)*r;if(!streetBlocked(x,y,.28))return[x,y];}return[g.x,g.y];}
function arrive(s,g,at){const wk=s.worker;if(g.kind==='bin'){const k=M.collectBin(s,g.id);if(k&&actor)actor.bubble={t:2,text:'收垃圾喽'};if(s.trash.cart>=M.CART)wk.trip.index=wk.trip.targets.length-1;else wk.trip.index++;}else if(g.kind==='litter'){M.pickLitter(s,g.id,at);wk.trip.index++;}else{M.unload(s);wk.trip=null;}wpath={key:'',path:[],next:-Infinity};}
function workerStep(s,at,mins){const wk=s.worker,day=Math.floor(at/1440),m=at-day*1440;if(!wk.trip){for(const [t,tag]of TRIPS){const key=day+':'+tag;if(m>=t&&m<t+360&&wk.lastTrip!==key&&!(tag==='am'&&wk.lastTrip===day+':pm')){M.planTrip(s,at,key);break;}}}
 let budget=Math.min(mins,720)*SPEED;let guard=0;while(wk.trip&&budget>1e-6&&guard++<80){const g=wk.trip.targets[wk.trip.index];if(!g){wk.trip=null;break;}if(g.kind==='litter'&&!s.trash.litter.some(l=>l.id===g.id&&l.collectedAt===null)){wk.trip.index++;continue;}
  const d=Math.hypot(g.x-wk.x,g.y-wk.y);if(d<=1.3){arrive(s,g,at);continue;}
  const key=wk.trip.key+':'+wk.trip.index;if(wpath.key!==key||!wpath.path.length){if(at<wpath.next&&wpath.key===key){break;}const goal=approach(g),path=SP.npcConflict?.route?.(wk.x,wk.y,goal[0],goal[1],streetBlocked,.28,6000)||[];wpath={key,path:path.length?path:[goal],next:at+1.5};}
  const q=wpath.path[0],dx=q[0]-wk.x,dy=q[1]-wk.y,l=Math.hypot(dx,dy);if(l<.05){wpath.path.shift();continue;}const stepLen=Math.min(l,budget);
  if(streetLive()&&actor&&SP.actors?.list?.includes(actor)&&mins<5){const ox=actor.x,oy=actor.y;const moved0=SP.actors.move?SP.actors.move(actor,dx/l*stepLen,dy/l*stepLen):0;wk.x=actor.x;wk.y=actor.y;const moved=Math.hypot(wk.x-ox,wk.y-oy);if(moved>1e-3)actor.dir=SP.dirFromWorld?.(wk.x-ox,wk.y-oy)||actor.dir;actor.update?.(mins*.98,moved>1e-3,actor.dir,moved);if(moved<stepLen*.3){wpath.next=at+.5;wpath.path=[];break;}void moved0;}
  else{wk.x+=dx/l*stepLen;wk.y+=dy/l*stepLen;}budget-=stepLen;if(stepLen>=l-1e-6)wpath.path.shift();}}
function syncActor(s){const show=streetLive()&&!G.trans;if(!show||!SP.Actor||!SP.actors?.list){if(actor&&SP.actors?.list)SP.actors.list=SP.actors.list.filter(a=>a!==actor);return;}if(!actor){const set=root.ACTORS?.nd_fit_work?'nd_fit_work':'uncle';actor=new SP.Actor({id:WORKER,set,name:'环卫老李',x:s.worker.x,y:s.worker.y,speed:SPEED,radius:.22,staff:true});SP.ensureActor?.(set);}if(!SP.actors.list.includes(actor)){actor.x=s.worker.x;actor.y=s.worker.y;actor.hidden=false;SP.actors.list.push(actor);}}
function tick(){if(working||!ps()||!G.ps.npcDailyLife)return;const s=state();if(!s)return;const at=now();if(lastAt===null||at<lastAt){lastAt=at;seen=ps().npcDailyLife.nextReceiptId||0;for(const o of M.RES)prevArea[o]=where(o);}const mins=at-lastAt;working=true;try{syncActor(s);workerStep(s,at,mins);if(at-s.lastAt>=.25){sync(s,at);discover(s,at);residentOrders(s,at);fulfil(s,at);residentTrash(s,at);cases(s,at);s.lastAt=Math.max(s.lastAt,at);}else if(mins>0){residentTrash(s,at);}lastAt=at;}finally{working=false;}}
/* player actions (menus) — each needs the player physically at the object */
const near=(o,r=2.4)=>!!o&&Math.hypot((SP.player?.x||0)-o.x,(SP.player?.y||0)-o.y)<r;
function freshness(r,at){const w=M.wearAt(r,at);return w>=1?'已经坏了':w>=.75?'快坏了':'还新鲜';}
function pantry(owner='player'){const s=state(),at=now(),rows=s.food.filter(r=>r.owner===owner);if(!rows.length)return'没有要冷藏或会坏的食材。';const g={};for(const r of rows){const k=PLACE[r.storage]+'·'+LABEL[r.item]+'('+freshness(r,at)+')';g[k]=(g[k]||0)+1;}return Object.entries(g).map(([k,n])=>k+'×'+n).join('；');}
function playerOrder(channel){const s=state(),at=now(),why=M.canOrder(s,'player');if(why)return why;if(!leased('player'))return'没有合租住处的租约，冰箱没地方放。';if(!(ps().money>=M.PRICE/100))return'钱不够（二手小冰箱60元）。';const z=M.order(s,{buyer:'player',channel,at,receiptId:null});if(!z.ok)return z.reason;ps().money=Math.round((ps().money-M.PRICE/100)*100)/100;if(ps().stats)ps().stats.spent=Math.round(((ps().stats.spent||0)+M.PRICE/100)*100)/100;return note(channel==='pickup'?'手机下单二手小冰箱（60元），3小时后到驿站快递柜，需本人去取。':'手机下单二手小冰箱（60元），约3小时后送货上门（09:00–21:00，需本人在家签收）。');}
function takeBag(){const s=state();if(!atHome('player'))return'要在合租屋里拎垃圾袋。';const n=s.trash.home.player;if(!n)return'家里没有垃圾。';s.trash.home.player=0;s.trash.carried.player+=n;return note(`拎起家里的垃圾袋（${n}件），出门找垃圾桶扔。`);}
function throwIn(id){const s=state(),b=M.BINS[id];if(SP.place?.where?.()!=='street'||!near(b))return'请走到垃圾桶旁。';if(!s.trash.carried.player)return'手里没有垃圾。';const k=M.drop(s,'player',id,s.trash.carried.player);if(!k)return b.name+'满了，扔不进去。';return note(`把${k}件垃圾扔进了${b.name}${s.trash.carried.player?`，还剩${s.trash.carried.player}件（桶满了）`:''}。`);}
function litter(){const s=state(),at=now();if(SP.place?.where?.()!=='street')return'只能在街上这么做。';if(!s.trash.carried.player)return'手里没有垃圾。';const l=M.litter(s,'player',SP.player.x,SP.player.y,at,s.trash.carried.player);if(!l)return'地上已经太多垃圾了。';
 const w=(SP.actors?.list||[]).filter(a=>a&&a!==SP.player&&!a.hidden&&a.id&&Math.hypot(a.x-SP.player.x,a.y-SP.player.y)<=8).sort((a,b)=>Math.hypot(a.x-SP.player.x,a.y-SP.player.y)-Math.hypot(b.x-SP.player.x,b.y-SP.player.y))[0];
 if(w){const id=String(w.id).replace(/[^A-Za-z0-9_:-]/g,'_').slice(0,60)||'witness';if(M.report(s,l.id,id,at)){w.bubble={t:2.5,text:'喂，怎么乱扔垃圾！我要反映给市容。'};return note(`把${l.units}件垃圾扔在了路边。${w.name||'路人'}看见了，说要举报。`);}}return note(`把${l.units}件垃圾扔在了路边，好像没人看见。`);}
function payFine(){const s=state(),at=now(),c=s.cases.find(c=>c.status==='fined'&&c.offender==='player');if(!c)return'没有待缴的市容罚款。';if(!(ps().money>=M.FINE/100))return'钱不够缴罚款（50元）。';ps().money=Math.round((ps().money-M.FINE/100)*100)/100;if(ps().stats)ps().stats.spent=Math.round(((ps().stats.spent||0)+M.FINE/100)*100)/100;M.pay(s,c,at);return note('扫码缴纳了50元市容罚款。');}
function pickup(){const s=state(),at=now(),o=s.orders.find(o=>o.buyer==='player'&&o.channel==='pickup');if(W?.sceneId!=='neighborhood_services'&&SP.place?.where?.()!=='neighborhood_services')return'要本人到驿站快递柜。';if(!o||o.status!=='arrived')return'快递柜里没有你的冰箱。';o.status='carried';o.handedAt=at;return note('从快递柜取出二手小冰箱，抱着走回合租屋房间安装。');}
function options(o){const s=state();if(!s||!o)return[];const out=[],id=o.id,at=now();
 if(id==='fridge'&&SP.place?.where?.()==='room_2f02'){out.push({id:'household_pantry',label:'看看冰箱里的食材',fn:()=>pantry('player')});if(s.trash.home.player)out.push({id:'household_bag',label:`拎起家中垃圾袋（${s.trash.home.player}件）`,fn:takeBag});}
 if(id==='shared_home_fridge'){out.push({id:'household_pantry',label:'看看我的食材',fn:()=>pantry('player')});if(s.trash.home.player)out.push({id:'household_bag',label:`拎起家中垃圾袋（${s.trash.home.player}件）`,fn:takeBag});const mine=s.orders.find(q=>q.buyer==='player');if(!mine){out.push({id:'household_order_delivery',label:'手机下单二手小冰箱 · 送货上门（¥60）',fn:()=>playerOrder('delivery')});out.push({id:'household_order_pickup',label:'手机下单二手小冰箱 · 驿站自提（¥60）',fn:()=>playerOrder('pickup')});}else out.push({id:'household_order_status',label:'查看冰箱订单',fn:()=>({ordered:'已下单，等待到货',arrived:'已到驿站快递柜，等你去取',carried:'正在搬回房间',handed:'已签收，进房间就能装好',installed:'已在你房间里运行'})[mine.status]+'。'});}
 if(M.BINS[id]&&SP.place?.where?.()==='street'){const b=M.BINS[id],n=s.trash.bins[id];out.push({id:'household_bin_look',label:`看看${b.name}（${n}/${b.cap}）`,fn:()=>`${b.name}里有${n}件，容量${b.cap}。`});if(s.trash.carried.player){out.push({id:'household_bin_throw',label:`把垃圾扔进桶里（手里${s.trash.carried.player}件）`,ok:M.binSpace(s,id)>0,fn:()=>throwIn(id)});if(!M.binSpace(s,id))out.push({id:'household_litter',label:'桶满了：放在桶边地上（乱丢）',fn:litter});}if(s.cases.some(c=>c.status==='fined'&&c.offender==='player'))out.push({id:'household_fine',label:'扫码缴纳市容罚款（¥50）',fn:payFine});}
 else if(SP.place?.where?.()==='street'&&s.trash.carried.player)out.push({id:'household_litter',label:`把垃圾随手扔在这儿（乱丢，${s.trash.carried.player}件）`,fn:litter});
 if(id===LOCKER&&s.orders.some(q=>q.buyer==='player'&&q.channel==='pickup'&&q.status==='arrived'))out.push({id:'household_pickup',label:'取出二手小冰箱（自提）',fn:pickup});
 return out;}
const open=G.openMenu;if(open)G.openMenu=function(o,opts){try{if(Array.isArray(opts)&&o&&!o.actor){const add=options(o).filter(q=>!opts.some(p=>p.id===q.id)).map(q=>({ok:true,...q}));if(add.length)opts=opts.concat(add);}}catch(e){root.console?.error?.(e);}return open.call(this,o,opts);};
if(G.update){const up=G.update;G.update=function(dt){const r=up.apply(this,arguments);try{tick();}catch(e){root.console?.error?.(e);}return r;};}
/* save/restore: the runtime proof that the ledger matches real holdings and resident receipts */
function prepare(s,at=now(),p=ps()){const n=M.prepare(s,at);if(!n)return null;const daily=p?.npcDailyLife?.blocks?SP.npcDailyLife?.prepare?.(p.npcDailyLife,at):p?.npcDailyLife;if(!daily?.residents)return null;
 for(const o of M.OWNERS)for(const k of M.FOODS[o]){const want=o==='player'?held(o,k,p):daily.residents[o].items[k];if(n.food.filter(r=>r.owner===o&&r.item===k).length!==want)return null;}
 for(const o of M.RES){const sp=daily.receipts.filter(r=>r.actorId===o&&r.kind==='spoil');for(const k of ['bread','drink'])if(sp.filter(r=>r.item===k).length!==n.discarded[o][k])return null;const ap=daily.receipts.filter(r=>r.actorId===o&&r.kind==='appliance'),ord=n.orders.filter(q=>q.buyer===o);if(ap.length!==ord.length||ap.some((r,i)=>r.id!==ord[i].receiptId||r.cents!==ord[i].cents||Math.abs(r.at-ord[i].orderedAt)>1e-6||r.to!==M.SELLER))return null;}
 return n;}
/* Site88: goods really handed over by a courier/locker enter holdings and the food ledger together (wear = time already spent at the door). */
function receive(owner,item,n,wear=0){if(owner!=='player'||!ps()||working)return 0;const s=state(),at=now();sync(s,at);let k=0;const home=atHome('player'),place=where('player');for(let i=0;i<n;i++){const st=home?M.homeStorage(s,'player',leased('player'),place):'carried';if(M.FOODS.player.includes(item)){if(!M.addFood(s,'player',item,at,st,Math.max(0,Math.min(1000,wear))))break;}ps().items[item]=(Math.floor(Number(ps().items[item])||0))+1;k++;}return k;}
function sanitize(){if(!ps()||working)return;const s=state();sync(s,now());}
function snapshot(){const s=state();if(!s)return null;sync(s,now());s.lastAt=Math.max(s.lastAt,now());return copy(s);}
